  <div class="stat" style="--c1:#ff5f9e;--c2:#e6316f;--glow:#ff4f9a"><div class="statIcon">♥</div><span class="delta">+12.4٪</span><small>تعامل امروز</small><strong>5,680</strong></div>
  <div class="stat" style="--c1:#a78bfa;--c2:#7c3aed;--glow:#9b5cff"><div class="statIcon">◌</div><span class="delta">+4.2٪</span><small>بازدید محتوا</small><strong>82.4K</strong></div>
  <div class="stat" style="--c1:#fbbf24;--c2:#f97316;--glow:#ffca5c"><div class="statIcon">⚡</div><span class="delta">+6.7٪</span><small>نرخ تعامل</small><strong>6.7٪</strong></div>
 </div>
 
<div class="card v15-mission motion" id="v15Mission">
