      <div class="v15-step pending"><i>3</i><span>Create • تأیید کاربر</span></div>
      <div class="v15-step"><i>4</i><span>Schedule • Queue</span></div>
      <div class="v15-step"><i>5</i><span>Publish • Instagram</span></div>
      <div class="v15-step"><i>6</i><span>Learn • بهبود بعدی</span></div>
    </div>
  </div>
